R.append((4002988,"लेमन तिरामिसू",None,"8","रेसिपी का 1/10",
["1 पैकेट (7oz) लेडीफ़िंगर कुकीज़",["सिरप","½ कप नींबू का रस, ताज़ा निचोड़ा हुआ"],["सिरप","½ कप पानी"],["सिरप","½ कप दानेदार चीनी"],["क्रीम","1 कप लाइट व्हिपिंग क्रीम"],["क्रीम","¼ कप दानेदार चीनी"],["क्रीम","1 कप मस्कारपोन चीज़"],["क्रीम","2 बड़े चम्मच नींबू का रस"],["सजावट","1 बड़ा चम्मच कोको पाउडर"]],
["एक छोटे सॉसपैन में नींबू का रस, पानी और चीनी उबालें। चीनी घुलने तक चलाएँ। आँच से उतारें और ठंडा होने दें।","एक कटोरे में क्रीम को इलेक्ट्रिक मिक्सर से फूलने तक फेंटें। चीनी, मस्कारपोन चीज़ और नींबू का रस डालें। सावधानी से मिलाएँ और एक तरफ़ रख दें।","आधी कुकीज़ को एक-एक करके ठंडे सिरप में डुबोएँ और एक आयताकार डिश (7\"×11\") में एक परत में अगल-बगल सजाएँ। कुकीज़ को डुबोते समय जल्दी करना सुनिश्चित करें। आप नहीं चाहते कि कुकीज़ गीली होकर बिखर जाएँ।","कुकीज़ की परत को चरण 2 के क्रीम मिश्रण के आधे हिस्से से ढकें।","बाकी आधी कुकीज़ को सिरप में डुबोएँ और क्रीम मिश्रण के ऊपर नई परत शुरू करें। अंत में बाकी क्रीम मिश्रण को ऊपर फैलाएँ।","छलनी से ऊपर कोको पाउडर छिड़कें। प्लास्टिक रैप से ढकें और परोसने से पहले 12 घंटे फ्रिज में रखें।"],
[["चीज़ प्लीज़!","सीमित मात्रा में, डेयरी को किडनी-अनुकूल आहार के हिस्से के रूप में खाया जा सकता है। चीज़, दही और दूध में स्वाभाविक रूप से पोटैशियम और फ़ॉस्फ़ोरस होता है, लेकिन ये खाद्य पदार्थ लाभकारी विटामिन, खनिज और कुछ प्रोटीन भी देते हैं, इसलिए यह तय करने के लिए कि कौन से डेयरी स्रोत और कितनी मात्रा आपके लिए सही है, पंजीकृत आहार विशेषज्ञ के साथ काम करना महत्वपूर्ण है।\n\nचीज़ कई अलग-अलग व्यंजनों में एक बहुमुखी सामग्री है। सोडियम, पोटैशियम और फ़ॉस्फ़ोरस की मात्रा चीज़ के प्रकार और मात्रा के अनुसार बदलती है।\n\nफ़ॉस्फ़ोरस और पोटैशियम में कम माने जाने वाले चीज़ आमतौर पर मुलायम होते हैं जैसे ब्री, क्रीम चीज़, मस्कारपोन और प्राकृतिक तीखा चेडर। लेबल पढ़ें, लेकिन इन विकल्पों के अधिकांश ब्रांडों में प्रति परोसे 200 मिलीग्राम या उससे कम सोडियम होता है।\n\nकॉटेज चीज़ को अक्सर किडनी-अनुकूल नाश्ते के रूप में प्रोत्साहित किया जाता है। अपना हिस्सा आधा कप तक सीमित रखें और ध्यान रखें कि बड़ी मात्रा में खाने पर इस खाद्य पदार्थ में फ़ॉस्फ़ोरस और सोडियम अधिक हो सकता है।\n\nप्रोसेस्ड चीज़ और चीज़ स्प्रेड बहुत कम खाने चाहिए।"]],
["1 स्टार्च","3 वसा","1 कार्बोहाइड्रेट"]))
R.append((4006743,"भुनी पीटा के साथ चिली-लाइम डिप",None,"8","4 चिप्स + 1½ बड़े चम्मच डिप",
[["डिप","1/2 कप सख़्त सिल्की टोफ़ू"],["डिप","2 बड़े चम्मच मेयोनेज़"],["डिप","1/2 कप जार से भुनी हुई लाल शिमला मिर्च"],["डिप","1 छोटा चम्मच लाल मिर्च पाउडर (चिली पाउडर)"],["डिप","1 छोटा चम्मच प्याज़ पाउडर"],["डिप","1 1/2 बड़े चम्मच नीबू का रस"],["डिप","3 बड़े चम्मच कटा हुआ ताज़ा धनिया*"],["पीटा चिप्स","4 सादी, मैदे की, ग्रीक पीटा ब्रेड (6 1/2 इंच व्यास की)"],["पीटा चिप्स","3 बड़े चम्मच जैतून का तेल"],["पीटा चिप्स","1 लहसुन की कली, कुचली हुई"]],
["ओवन को 300°F पर पहले से गरम करें।","डिप तैयार करने के लिए, डिप की सभी सूचीबद्ध सामग्री को ब्लेंडर या फ़ूड प्रोसेसर में डालें और लगभग 30 सेकंड तक चिकना होने तक ब्लेंड करें।","एक छोटे कटोरे में डालें, ढकें और कम से कम 30 मिनट फ्रिज में रखें।","जैतून के तेल को लहसुन के साथ मिलाएँ और पीटा पर लगाएँ।","हर पीटा को 8 फाँकों में काटें, फिर फाँकों को बेकिंग ट्रे पर रखें और 20 मिनट या चिप्स के कुरकुरे होने, लेकिन भूरे न होने तक भूनें।","डिप और पीटा चिप्स को प्लेट में सजाएँ और परोसें।"],
["* इसकी जगह ताज़ा सोआ या अजमोद (पार्सले) डाला जा सकता है","यह डिप कच्ची सब्ज़ियों के साथ या सैंडविच स्प्रेड के रूप में अच्छा लगता है।","आप पीटा की फाँकों को एक डिब्बे में एक सप्ताह तक रख सकते हैं।",["टोफ़ू और पौधे-आधारित प्रोटीन","पर्याप्त प्रोटीन खाना किडनी आहार का एक महत्वपूर्ण हिस्सा है। बहुत कम प्रोटीन के सेवन से मांसपेशियों की हानि हो सकती है, जबकि बहुत अधिक खाने से आपकी किडनी को अधिक मेहनत करनी पड़ती है। आपको कितने प्रोटीन की ज़रूरत है यह तय करने में पंजीकृत आहार विशेषज्ञ के साथ काम करना सहायक हो सकता है। जानवरों और पौधों से प्रोटीन के विभिन्न स्रोतों को शामिल करने से आपका आहार अधिक रोचक बन सकता है।\n\nटोफ़ू उच्च प्रोटीन, कम वसा वाले खाद्य पदार्थ का एक उदाहरण है जिसे मांस की जगह उपयोग किया जा सकता है। टोफ़ू सोयाबीन के दही से बनता है और नरम से लेकर अतिरिक्त सख़्त तक विभिन्न बनावटों में खरीदा जा सकता है। USDA न्यूट्रिएंट डेटाबेस के अनुसार, सख़्त टोफ़ू के ½ कप हिस्से में 22 ग्राम प्रोटीन, 18 मिलीग्राम सोडियम, 299 मिलीग्राम पोटैशियम और 239 मिलीग्राम फ़ॉस्फ़ोरस होता है। घर के बने नगेट्स बनाने के लिए चिकन की जगह, बुरिटो में अंडे के विकल्प के रूप में, या सैंडविच या सलाद के हिस्से के रूप में ग्रिल करके टोफ़ू का उपयोग करें।"]],
["1 स्टार्च","1 वसा"]))
